// Collection message for a client with overdue receivables, to copy and paste into WhatsApp (until
// a WhatsApp API is integrated). Pure: the dialog passes the time, the workspace name and the mode.

import { addMonthKey, formatBRL, formatDateBR, monthKey, onlyDigits, type DelinquencyClient, type ISODate, type MonthKey } from '@effinance/shared';

/**
 * Which month a fee refers to (competência) when the receivable does not say it (fees generated by
 * "Gerar honorários" carry their own). Fees are billed after the month of service, so by default a
 * fee due on 15/01/2026 is the 12/2025 fee ('previous'); 'due' uses the due month itself.
 */
export type CompetenceMode = 'previous' | 'due';

export const COMPETENCE_MODE_LABELS: Record<CompetenceMode, string> = {
  previous: 'Mês anterior ao vencimento',
  due: 'Mês do vencimento',
};

export interface CollectionItem {
  /** Due date. */
  date: ISODate;
  /** Cents. */
  amount: number;
  /** Real competence month (generated fees); null/absent → derived from the due date. */
  competence?: MonthKey | null;
}

export interface CollectionMessageInput {
  /** As the client should be addressed (see collectionName). */
  clientName: string;
  items: readonly CollectionItem[];
  /** Closing line: the workspace (accounting office) name. */
  signature: string;
  /** Picks the greeting. */
  now: Date;
  /** Fallback for items without their own competence. */
  competence?: CompetenceMode;
}

/** Greeting by the local time: Bom dia (5h–11h), Boa tarde (12h–17h), Boa noite (18h–4h). */
export function greeting(now: Date): 'Bom dia' | 'Boa tarde' | 'Boa noite' {
  const hour = now.getHours();
  if (hour >= 5 && hour < 12) return 'Bom dia';
  if (hour >= 12 && hour < 18) return 'Boa tarde';
  return 'Boa noite';
}

/** Trade name (nome fantasia), falling back to the razão social. */
export function collectionName(client: Pick<DelinquencyClient, 'name' | 'tradeName'>): string {
  return client.tradeName?.trim() || client.name.trim();
}

const MONTH_KEY = /^\d{4}-(0[1-9]|1[0-2])$/;

/** True when the item carries its own competence month (a valid 'YYYY-MM'). */
export function hasOwnCompetence(item: Pick<CollectionItem, 'competence'>): boolean {
  return typeof item.competence === 'string' && MONTH_KEY.test(item.competence);
}

/** "MM/AAAA" of an item: its own competence when set, else derived from the due date by `mode`. */
export function competenceOf(item: Pick<CollectionItem, 'date' | 'competence'>, mode: CompetenceMode = 'previous'): string {
  const month = hasOwnCompetence(item) ? item.competence! : mode === 'previous' ? addMonthKey(monthKey(item.date), -1) : monthKey(item.date);
  return `${month.slice(5, 7)}/${month.slice(0, 4)}`;
}

/** "• 12/2025 | R$ 350,00 | Venc 15/01/2026" */
export function collectionLine(item: CollectionItem, mode: CompetenceMode = 'previous'): string {
  return `• ${competenceOf(item, mode)} | ${formatBRL(item.amount)} | Venc ${formatDateBR(item.date)}`;
}

/**
 * One line per competence month and due date (oldest first): the fee and its "+ Empregados" charge
 * of the same month are summed into one line, as in the office's model.
 */
export function groupByMonth(items: readonly CollectionItem[], mode: CompetenceMode = 'previous'): CollectionItem[] {
  const groups = new Map<string, CollectionItem>();
  for (const item of items) {
    const key = `${competenceOf(item, mode)}|${item.date}`;
    const current = groups.get(key);
    groups.set(key, current ? { ...current, amount: current.amount + item.amount } : { ...item });
  }
  return [...groups.values()].sort((a, b) => a.date.localeCompare(b.date) || competenceOf(a, mode).localeCompare(competenceOf(b, mode)));
}

/** The standard message of the office, with one line per open month (oldest first). */
export function buildCollectionMessage({ clientName, items, signature, now, competence = 'previous' }: CollectionMessageInput): string {
  const lines = groupByMonth(items, competence).map((item) => collectionLine(item, competence));
  const closing = signature.trim() ? `Atenciosamente,\n${signature.trim()}` : 'Atenciosamente,';
  return [
    `${greeting(now)}, ${clientName.trim()}`,
    'Até o momento, não identificamos o pagamento dos honorários relacionados abaixo. Solicitamos, por gentileza, que o pagamento seja realizado com a maior brevidade possível.',
    lines.join('\n'),
    'Caso o pagamento já tenha sido efetuado, solicitamos, por gentileza, o envio do comprovante para atualização em nosso sistema.',
    closing,
  ].join('\n\n');
}

/** Area code (no zeros) + mobile (9 + 8 digits) or landline (2–8 + 7 digits). */
const BR_NATIONAL_PHONE = /^[1-9]{2}(?:9\d{8}|[2-8]\d{7})$/;

/**
 * WhatsApp number in international format (digits only). Brazilian numbers with area code
 * (an optional leading trunk 0 removed) get the 55 country code; numbers that already carry it
 * are kept. Anything that is not a Brazilian mobile or landline is null.
 */
export function whatsappNumber(phone: string | null | undefined): string | null {
  const digits = onlyDigits(phone).replace(/^0+/, '');
  if (BR_NATIONAL_PHONE.test(digits)) return `55${digits}`;
  if (digits.startsWith('55') && BR_NATIONAL_PHONE.test(digits.slice(2))) return digits;
  return null;
}

/** `https://wa.me/<number>?text=<message>`; null when the phone cannot be used. */
export function whatsappHref(phone: string | null | undefined, text: string): string | null {
  const number = whatsappNumber(phone);
  return number ? `https://wa.me/${number}?text=${encodeURIComponent(text)}` : null;
}
